const PYTHON_API_URL_V2 = process.env.PYTHON_API_URL_V2;
// const staleTime = 50 * 60 * 1000; // Specifying staleTime means queries will not refetch their data as often

const getSessionEvents = async (postBody) => axiosInstance.post(`${PYTHON_API_URL_V2}/sessions/get-event-details`, postBody, {
    withCredentials: true,
    credentials: 'include',
  })

export const useSessionEvents = (postBody, enabled) => useQuery(['sessionEvents', postBody], () => getSessionEvents(postBody), {
  keepPreviousData: true,
  enabled,
});

