const getSessionDetail = async (postBody) => axiosInstance.post(`${process.env.PYTHON_API_URL}/sessions/get-details`, postBody, {
  withCredentials: true,
  credentials: 'include',
})
.then(({ data: { data: respData } }) => respData)
.catch((error) => 
   error?.response?.data
  // setSessionDetail(error?.response?.data);
);

export const useSessionDetail = (queryKey, postBody) => useQuery(
  [queryKey],
  () =>
    getSessionDetail(postBody),
  {
    // staleTime,
    suspense: true,
    retry: 3,
    refetchOnWindowFocus: false,
    enabled: !!postBody?.sessionid,
  }
);

