const SharedSessionPage = () => {
  const containerRef = useRef();
  const { sessionDetail,
    setSessionDetail,
    setSessionBugInfo,
    setSessionGestures,
} = useSessionTimeLine();
  const dispatch = useDispatch();
  const { selectedHeaderField } = useSessionHeader();
  const { urlReducer: urlQuery, appFilter } = useSelector((state) => state);
  const sessionDetailSize = appFilter?.sessionDetailSize;
  const shareKey = urlQuery.shareSessionKey;

  const { data: gesturesData } = useShareSessionData(
    'gesture-details',
    '/sessions/get-gesture-details/',
    shareKey
  );

  const { data: recordingSettingDetails } = useRecordingSettingsDetails( shareKey )

  const { data: bugInfoData } = useShareSessionData(
    'session-bug-details',
    '/sessions/get-session-bug-details/',
    shareKey
  );
  const { data: sessionData, error } = useShareSessionDetails(
    'get-details',
    '/sessions/get-details/',
    shareKey
  );
  const { data: renameScreens } = useRenameScreensList(
    'rename-screens',
    '/screen/display-screens-list/',
    shareKey
  );
  const saveDetailSize = (key, value) =>
    dispatch(setSessionDetailSizeByKey(key, value));

  const multiScreenSkippedData = useScreenSkippedData()

  useEffect(() => {
    if (gesturesData) {
      setSessionGestures(gesturesData?.data?.data);
    }
  }, [gesturesData, setSessionGestures]);


  useEffect(() => {
    if (sessionData?.data?.data) {
      const sessionDetails = {
        ...sessionData?.data?.data,
        isNativeScreenCaptureEnabled: recordingSettingDetails?.data?.data?.isNativeScreenCaptureEnabled,
      }
      setSessionDetail(sessionDetails);
    }
  }, [sessionData?.data?.data, recordingSettingDetails?.data?.data, setSessionDetail]);


  useEffect(() => {
    if (bugInfoData) {
      setSessionBugInfo(bugInfoData?.data?.data);
    }
  }, [bugInfoData, bugInfoData?.data?.data]);

  useEffect(()=>{
    if(renameScreens?.data?.data){
      dispatch(gotScreenRenamedList(renameScreens.data.data))
    }

  }, [renameScreens])

  const toggleFullScreen = useCallback(() => {
    const container = containerRef.current;
    const isFullScreen = document.webkitCurrentFullScreenElement;
    const isFireFoxFullScreen = document.mozFullScreenElement;
    if (container) {
      if (isFullScreen) {
        document.webkitExitFullscreen && document.webkitExitFullscreen();
      } else {
        container.webkitRequestFullscreen &&
          container.webkitRequestFullscreen();
      }
      if (isFireFoxFullScreen) {
        document.mozCancelFullScreen && document.mozCancelFullScreen();
      } else {
        container.mozRequestFullScreen && container.mozRequestFullScreen();
      }
    }
  }, []);

  const errorMessage = error?.response?.data?.error?.message;

  return (
    <Wrapper>
        <div className="public-header">
          <div className="logo-box">
            <a href="https://uxcam.com" target="_blank" rel="noreferrer">
              <img src="/static/uxcam-new-logo.svg" alt="UXCam" />
            </a>
          </div>
          {sessionDetail?.appName ?
          <h2>
            {`${'Publicly shared session from '}${
              sessionDetail?.appName
            }'`}
          </h2> : ''}
        </div>
        {sessionDetail?.appName ? (
          <h2>
            {`${'Publicly shared session from '}${sessionDetail?.appName}'`}
          </h2>
        ) : (
          ''
        )}
      {sessionDetail && !isEmpty(sessionDetail) ? (
        <Main ref={containerRef}>
          <Box aria-label="video" className="middle-panel">
            <Container>
              <SessionDetailsHeader session={sessionDetail} />
              {selectedHeaderField === 'sessionVideo' ? (
                <SessionVideo
                  session={sessionDetail}
                  toggleFullScreen={toggleFullScreen}
                  multiScreenSkippedData={multiScreenSkippedData}
                />
              ) : null}
              {selectedHeaderField?.includes('crash') ? <StackTrace /> : null}
              {selectedHeaderField?.includes('exception') ? <BugTrace /> : null}
              {selectedHeaderField?.includes('UIFreeze') ? <AnrTrace /> : null}
            </Container>
          </Box>
          <ResizePanel
            direction="w"
            handleClass="resize-handle"
            containerClass="resize-panel-container-second"
            borderClass="resize-border"
            initialWidth={sessionDetailSize?.end}
            saveDetailSize={saveDetailSize}
          >
            <Box>
              <SessionDetailSideBar multiScreenSkippedData={multiScreenSkippedData} />
            </Box>
          </ResizePanel>
        </Main>
      ) : (
        <ErrorContainer>
          <ErrorMessage>
            <p dangerouslySetInnerHTML={{ __html: errorMessage }} />
          </ErrorMessage>
        </ErrorContainer>
      )}
    </Wrapper>
  );
};
export default SharedSessionPage;
