import { sanitizeUrl } from "@braintree/sanitize-url";

const BASE_URL = process.env.REDIRECT_URL;

// Our apex domain and any subdomain of it (e.g. SSO endpoints on api.uxcam.com).
const isUxcamHost = (hostname) => {
  const host = (hostname || '').toLowerCase();
  return host === 'uxcam.com' || host.endsWith('.uxcam.com');
};

const resolveRedirectUrl = (url) => {
  const sanitizedUrl = sanitizeUrl(url || '');
  // sanitize-url collapses dangerous schemes (javascript:, data:, ...) to this.
  if (!sanitizedUrl || sanitizedUrl === 'about:blank') return '/dashboard';
  try {
    // Resolve against our own origin so relative paths stay on-site and
    // absolute URLs expose a real host we can validate. Validating the parsed
    // hostname (instead of string-matching the URL) is what closes the bypass.
    const parsed = new URL(sanitizedUrl, BASE_URL);
    const isHttp = parsed.protocol === 'https:' || parsed.protocol === 'http:';
    // Allow redirects back to our own origin (covers relative paths and any
    // local/staging host) or to a uxcam.com host.
    const sameOrigin = BASE_URL ? parsed.origin === new URL(BASE_URL).origin : false;
    if (isHttp && (sameOrigin || isUxcamHost(parsed.hostname))) return parsed.href;
  } catch {
    // malformed URL -> fall through to the safe default
  }
  return '/dashboard';
};

const redirectUrlHandler = (url, res) => {
  const redirectUrl = resolveRedirectUrl(url);
  if (res) res.redirect(redirectUrl);
  else window.location.href = redirectUrl;
};

export default redirectUrlHandler;
