import React from 'react'
import { SessionVideoProviderV2 } from 'components/shared/Sessions/Context'
import { NoCodeEventsContextProvider } from 'components/features/sessions/Context/NoCodeEventsContext'
import { FeatureFlagsContextProvider } from 'components/common/Contexts/FeatureFlagsContext';
import { AISidebarContextProvider } from 'components/common/Contexts/AISidebarContext';
import { useSelector } from 'react-redux'
import SharedSessionPage from './SharedSessionPage'

const SharedSession = () => {
	const { urlReducer } = useSelector( state => state )

	return (
		<SessionVideoProviderV2 appId={ urlReducer?.appId } sessionId={ urlReducer?.sessionid }>
			<FeatureFlagsContextProvider>
				<AISidebarContextProvider>
					<NoCodeEventsContextProvider appId={ urlReducer?.appId }>
						<SharedSessionPage />
					</NoCodeEventsContextProvider>
				</AISidebarContextProvider>
			</FeatureFlagsContextProvider>
		</SessionVideoProviderV2>
	)
}

export default SharedSession