export const getAppDropdown = (getCookies, isServer) => (dispatch, getState) =>
  AppApi.getAppDropdown(getCookies || getState().tokenReducer, isServer)
    .then(async (res) => {
      const jsonResponseOrNull = isServer ? await res.json() : null;
      const resData = isServer ? jsonResponseOrNull.data : res.data.data;
      dispatch(gotAppDropdown(resData));
      return resData;
    })
    .catch((error) => {
      getErrorHandle(dispatch, gotAppDropdown, error.response, 'dashboard');
      return error.response;
    });

export const getOrgCsrf = () => (dispatch, getState) =>
  AppApi.getOrgCsrf(getState().tokenReducer)
    .then(async (res) => {
      if (res.ok) {
        const orgCsrfJson = await res.json();
        dispatch(
          gotCsrf({
            csrf: orgCsrfJson.data.csrf.token,
            orgExist: false,
            appExist: false,
          })
        );
        return {
          orgCsrf: res,
          csrf: orgCsrfJson.data.csrf.token,
          orgExist: false,
          appExist: false,
        };
      }
      throw res;
    })
    .catch((error) => getErrorHandle(dispatch, gotCsrf, error));

export const getAppCsrf = () => (dispatch, getState) =>
  AppApi.getAppCsrf(getState().tokenReducer)
