export const createOrganization = (data) => async (dispatch, getState) => {
  const csrf = await dispatch(getCsrf());
  data['_csrf'] = csrf;
  return AppApi.createOrg(data, getState().tokenReducer).then(
    (res) => {
      if (res.success) {
        const orgs = {};
        orgs.name = res.data.organization.name;
        orgs.orgId = res.data.organization['_id'];
        orgs.apps = [];
        dispatch(gotAppDropdown([orgs]));
        dispatch(gotCsrf({ csrf: '', orgExist: true, appExist: false }));
        window.dataLayer = window.dataLayer || [];
        window.dataLayer.push({
          event: 'organization-created',
          orgID: res.data.organization['_id'],
          orgName: res.data.organization.name,
        });
        return { orgExist: true, appExist: false };
      }
      // notificationOpts.message = res.error.message;
      // dispatch(error(notificationOpts))
    },
    (error) => postErrorHandle(dispatch, undefined, error.response)
  );
};

export const installCode = (appId, cookies) => (dispatch, getState) =>
  AppApi.installCode(getState().urlReducer.appId, cookies)
    .then(async (res) => {
      if (res.status === 200) {
        const resJson = res.data;
        const currentApp = _.clone(getState().currentAppReducer);
        const checkList = getState().appChecklistReducer;
        if (!currentApp?.isIntegrated) {
          currentApp.isIntegrated = resJson.data.isIntegrated;
          checkList.isSDKIntegrated = resJson.data.isIntegrated;
        }
        // dispatch(gotAppDropdown(orgList))
        dispatch(gotAppCheckList(checkList));
        dispatch(gotCurrentApp(currentApp));
        return resJson.data;
      }
      throw res;
    })
    .catch(async (error) => getErrorHandle(dispatch, gotCurrentApp, error));

export const getCurrentApp = (appId, orgList) => (dispatch, getState) => {
  const orgs = orgList || getState().applicationReducer || [];
  let app;
  orgs.some((org) =>
    org.apps.some((apps) => {
      if (apps?.['_id'] === appId) {
        app = apps;
        return true;
      }
    })
  );

  if (!app && appId !== 'undefined') {
    AppApi.getApp(appId, getState().tokenReducer)
      .then(async (res) => {
        dispatch(gotCurrentApp(res.data.data));
        return res.data.data;
      })
      .catch(() => {
        // getErrorHandle(dispatch, gotCurrentApp, error);
         Router.push('/error?errorStatus=406');
      });
  }

  typeof app !== 'undefined' && dispatch(gotCurrentApp(app));
  return app;
};

