import React, { createContext, useContext, useState, useMemo, useCallback, useRef } from 'react';

const AISidebarContext = createContext();

const CHAT_MINIMIZE_KEY = 'uxcam_chat_minimize';

const getLocalMinimizeState = (appId) => {
  try {
    const stored = localStorage.getItem(`${CHAT_MINIMIZE_KEY}_${appId}`);
    return stored !== null ? JSON.parse(stored) : null;
  } catch (e) {
    return null;
  }
};

const setLocalMinimizeState = (appId, minimize) => {
  try {
    localStorage.setItem(`${CHAT_MINIMIZE_KEY}_${appId}`, JSON.stringify(minimize));
  } catch (e) { /* noop */ }
};

export const useAISidebarContext = () => {
  const context = useContext(AISidebarContext);
  if (!context) {
    throw new Error('useAISidebarContext must be used within an AISidebarContextProvider');
  }
  return context;
};

export const AISidebarContextProvider = ({ children, initialMinimizeState = false, appId }) => {
  const [isVisible, setIsVisible] = useState(() => {
    if (appId) {
      const localState = getLocalMinimizeState(appId);
      if (localState !== null) return !localState;
    }
    return !initialMinimizeState;
  });
  const [isExpanded, setIsExpanded] = useState(false);
  const [debugMode, setDebugMode] = useState(false);
  const hasInitializedRef = useRef(false);

  React.useEffect(() => {
    if (!hasInitializedRef.current) {
      hasInitializedRef.current = true;
      return;
    }
    if (appId) {
      const localState = getLocalMinimizeState(appId);
      if (localState !== null) {
        setIsVisible(!localState);
        return;
      }
    }
    setIsVisible(!initialMinimizeState);
  }, [initialMinimizeState, appId]);

  const toggleVisibility = useCallback(() => {
    const newVisibility = !isVisible;
    setIsVisible(newVisibility);

    if (appId) {
      setLocalMinimizeState(appId, !newVisibility);
    }
  }, [isVisible, appId]);

  const toggleExpansion = useCallback(() => setIsExpanded(!isExpanded), [isExpanded]);
  const toggleDebugMode = useCallback(() => setDebugMode(!debugMode), [debugMode]);

  const setInitialVisibility = useCallback((minimize) => {
    setIsVisible(!minimize);
  }, []);

  const value = useMemo(() => ({
    isVisible,
    isExpanded,
    toggleVisibility,
    toggleExpansion,
    debugMode,
    toggleDebugMode,
    setInitialVisibility,
  }), [isVisible, isExpanded, toggleVisibility, toggleExpansion, debugMode, toggleDebugMode, setInitialVisibility]);

  return (
    <AISidebarContext.Provider value={value}>
      {children}
    </AISidebarContext.Provider>
  );
};