import { AUTH } from 'types'
import authApi from 'services/authApi'

export const UXCamAuth = (data, type) => ({
    type: type || AUTH,
    data,
  })

export const setAuthValuesByStep = (payload, step) => async (
  dispatch,
  getState
) => {
  const authData = JSON.parse(JSON.stringify(getState().auth))
  authData['_formData'] = {
    ...authData['_formData'],
    [`step_${step + 1}_data`]: payload,
  }
  await dispatch(UXCamAuth(authData))
}

export const checkEmail = (data) => async () => authApi
    .checkEmailExistOrNot(data)
    .then((res) => res)
    .catch((error) => error.response)

export const setKeyByValue = (key, value) => async (dispatch, getState) => {
  const authData = JSON.parse(JSON.stringify(getState().auth))
  authData[key] = value
  await dispatch(UXCamAuth(authData))
}
