import _ from 'underscore';

import { SCREEN_RENAME } from 'types'
import screenApi from 'services/screenApi'
import { gotAppCheckList } from './appdropdown'

export const gotScreenRenamedList = data => ({
    type: SCREEN_RENAME,
    data
  })

export const customScreenName = (data) => async (dispatch, getState) => {
  const checkList = getState().appChecklistReducer

  return screenApi.customScreenName(data).then(async res => {
    if (res.status === 200) {
      dispatch(gotScreenRenamedList(res.data.data))
      if (!checkList.isAppScreenRenamed) {
        checkList.isAppScreenRenamed = true
        dispatch(gotAppCheckList(checkList))
      }
      return res.data.data
    } if (res.status === 400) {
      return res
    }
    return null;
  }).catch(error => error.response)
}

export const getScreenNameList = (appIdFromData) => async (dispatch, getState) => {
  const appid = appIdFromData || getState().currentAppReducer['_id'] || getState().urlReducer.appId
  await dispatch(gotScreenRenamedList({}))
  return screenApi.getScreenEditedList(appid).then(async res => {
    dispatch(gotScreenRenamedList(res.data.data))
    return res.data.data
  }).catch(error => error)
}
