// eslint-disable-next-line import/prefer-default-export
import { useMemo } from 'react';
import { clone } from 'lodash';
import { useSelector } from 'react-redux';
import { consecutiveRanges, range } from 'Utils/helpers/commonUtils';
import { useSessionTimeLine } from 'components/shared/Sessions/Context';

export const useScreenSkippedData = () => {
  const { sessionDetail } = useSessionTimeLine();
  const screenTimeLineData = useMemo( () => sessionDetail?.screenTimeline?.activities || [], [sessionDetail] );
  const { selectedScreens = [] } = useSelector((state) => state.screenTimelineReducer);
  const skipData = useMemo(() => {
    if (!screenTimeLineData.length) return {};
    let screenTimeLineDataCloned = clone(screenTimeLineData);
    let seqArray = [];
    let seqArrayIndexList = [];
    if (screenTimeLineDataCloned?.length) {
      // assign index to each timeline data
      screenTimeLineDataCloned = screenTimeLineDataCloned.map((v, i) => {
        // eslint-disable-next-line no-param-reassign
        v['screenIndex'] = i;
        return v;
      });
      // filter out the list that is not included on screens dropdown
      const excludedList = screenTimeLineDataCloned.filter( ({ activityName }) => !selectedScreens.includes(activityName) );
      const indexOfExcludedList = excludedList.map((v) => v.screenIndex)
      if (excludedList.length) seqArray = consecutiveRanges(indexOfExcludedList);
      seqArrayIndexList = seqArray.filter((v) => v.includes('->'));
      seqArrayIndexList = seqArrayIndexList.map((v) => {
        let vl = v;
        vl = v.includes('->') ? v.split('->') : v;
        vl = v.includes('->')
          ? range(Number(vl[0]), Number(vl[1]))
          : [Number(vl)];
        return vl;
      });
      seqArray = seqArrayIndexList.map((v) =>
        v.map((o) => screenTimeLineDataCloned[o])
      );
    }
    if (seqArrayIndexList.length) {
      seqArrayIndexList.map((v, i) => {
        screenTimeLineDataCloned.splice(v[0], 1, seqArray[i]);
        return v;
      });
      const combinedArrayListWithout1st = seqArrayIndexList
        .map((v) => {
          v.shift();
          return v;
        })
        .reduce((a, b) => a.concat(b), []);
      screenTimeLineDataCloned = screenTimeLineDataCloned.filter(
        (v, i) => !combinedArrayListWithout1st.includes(i)
      );
    }
    return { screenTimeLineDataCloned, seqArrayIndexList: seqArray };
  }, [screenTimeLineData, selectedScreens]);
  return skipData;
};

export default useScreenSkippedData;
